rollback.sql:

DO $$
DECLARE
    v_duplicate_count INT;
BEGIN
    SELECT count(*) INTO v_duplicate_count
    FROM (
        SELECT meter_id, reading_date
        FROM utility_readings
        GROUP BY meter_id, reading_date
        HAVING count(*) > 1
    ) dupes;

    IF v_duplicate_count > 0 THEN
        RAISE EXCEPTION 'KHONG THE ROLLBACK: Ton tai % cap (meter_id, reading_date) trung lap giua ban ghi hoat dong va ban ghi xoa mem. Can DBA xu ly thu cong de dam bao toan ven du lieu.', v_duplicate_count;
    END IF;
END $$;
